-- Migration: Create profiles table
-- PROJ-1: User Authentication
-- Created: 2026-02-21
--
-- The profiles table extends Supabase Auth user data with application-level
-- fields. It is linked 1:1 to auth.users via the id foreign key.

-- ============================================================
-- 1. Create the profiles table
-- ============================================================
CREATE TABLE IF NOT EXISTS public.profiles (
  -- Primary key mirrors auth.users.id (UUID generated by Supabase Auth)
  id          UUID PRIMARY KEY REFERENCES auth.users (id) ON DELETE CASCADE,

  -- Display name (optional, can be set by user later)
  display_name TEXT,

  -- Role for admin moderation (PROJ-5)
  -- Values: 'user' | 'admin'
  role        TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'admin')),

  -- Timestamps
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ============================================================
-- 2. Add a comment for documentation
-- ============================================================
COMMENT ON TABLE public.profiles IS
  'Application-level user profile data, linked 1:1 to auth.users.';

COMMENT ON COLUMN public.profiles.id IS
  'References auth.users.id. Cascades delete when the auth user is deleted.';

COMMENT ON COLUMN public.profiles.role IS
  'Application role: ''user'' (default) or ''admin'' (for moderation in PROJ-5).';

-- ============================================================
-- 3. Indexes for frequently queried columns
-- ============================================================

-- Index on role to support fast admin look-ups (PROJ-5)
CREATE INDEX IF NOT EXISTS idx_profiles_role ON public.profiles (role);

-- ============================================================
-- 4. Auto-update updated_at on every row change
-- ============================================================
CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_profiles_updated_at
  BEFORE UPDATE ON public.profiles
  FOR EACH ROW
  EXECUTE FUNCTION public.set_updated_at();

-- ============================================================
-- 5. Auto-create a profile row when a new auth user is created
-- ============================================================
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  INSERT INTO public.profiles (id)
  VALUES (NEW.id)
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_new_user();

-- ============================================================
-- 6. Enable Row Level Security
-- ============================================================
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;

-- ============================================================
-- 7. RLS Policies
-- ============================================================

-- SELECT: authenticated users can read their own profile
--         (other features may add a broader read policy later, e.g. public display names)
CREATE POLICY "profiles: owner can select own row"
  ON public.profiles
  FOR SELECT
  TO authenticated
  USING (auth.uid() = id);

-- INSERT: blocked via RLS — profile rows are created only by the
--         handle_new_user() trigger (SECURITY DEFINER), so direct inserts are denied.
CREATE POLICY "profiles: no direct insert"
  ON public.profiles
  FOR INSERT
  TO authenticated
  WITH CHECK (false);

-- UPDATE: authenticated users can update only their own profile row,
--         and they cannot change their own id or role
CREATE POLICY "profiles: owner can update own row"
  ON public.profiles
  FOR UPDATE
  TO authenticated
  USING (auth.uid() = id)
  WITH CHECK (auth.uid() = id);

-- DELETE: blocked — profile deletion is handled by ON DELETE CASCADE
--         from auth.users; users cannot manually delete their profile row
CREATE POLICY "profiles: no direct delete"
  ON public.profiles
  FOR DELETE
  TO authenticated
  USING (false);
